/**
 * Image Generation Service
 * Client for OpenRouter API using Gemini 2.5 Flash Preview Image model for outfit visualization
 *
 * Features:
 * - Fashion-specific prompt engineering
 * - Error handling with retries
 * - Timeout protection
 * - Rate limiting awareness
 */

import type { ImageGenerationRequest, ImageGenerationResponse } from '../types/image-types';

/**
 * OpenRouter API configuration
 */
const OPENROUTER_CONFIG = {
  /** OpenRouter API base URL */
  baseUrl: 'https://openrouter.ai/api/v1',
  /**
   * Model ID for Gemini 3 Pro Image Preview - Nano Banana Pro (text-to-image capable)
   * Google's most advanced image-generation and editing model
   */
  model: 'google/gemini-2.5-flash-image',
  /** Request timeout in milliseconds */
  timeout: 30000,
  /** Maximum retry attempts on failure */
  maxRetries: 2,
  /** Exponential backoff base delay (ms) */
  retryDelay: 1000,
};

/**
 * OpenRouter Image Generation Client
 * Handles communication with OpenRouter API for outfit image generation
 */
export class OpenRouterImageClient {
  private apiKey: string;
  private requestCount: number = 0;
  private lastRequestTime: number = 0;

  /**
   * Creates a new OpenRouter image client
   *
   * @param apiKey - OpenRouter API key
   * @throws Error if API key is not provided
   */
  constructor(apiKey: string) {
    if (!apiKey || typeof apiKey !== 'string' || apiKey.trim() === '') {
      throw new Error('OpenRouter API key is required');
    }
    this.apiKey = apiKey;
  }

  /**
   * Configuration for fitting model generation
   */
  private static readonly FITTING_MODEL_CONFIG = {
    /** Extended timeout for fitting model generation (60 seconds) */
    timeout: 60000,
  };

  /**
   * Generates an outfit image from description using Gemini 2.5 Flash Preview
   *
   * @param description - Outfit description extracted from conversation
   * @param options - Optional style parameters
   * @returns Promise resolving to image generation response
   *
   * @example
   * const client = new OpenRouterImageClient(apiKey);
   * const response = await client.generateOutfitImage(
   *   "White shirt with black pants for business meeting",
   *   { style: { composition: 'flat-lay' } }
   * );
   */
  async generateOutfitImage(
    description: string,
    options?: ImageGenerationRequest['style']
  ): Promise<ImageGenerationResponse> {
    // Validate input
    if (!description || typeof description !== 'string' || description.trim() === '') {
      return {
        success: false,
        error: 'INVALID_DESCRIPTION',
        message: 'Outfit description is required',
      };
    }

    // Check client-side rate limiting (basic protection)
    if (!this.checkRateLimit()) {
      return {
        success: false,
        error: 'RATE_LIMITED',
        message: 'Too many requests. Please wait a moment before trying again.',
      };
    }

    // Attempt generation with retries
    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
      try {
        if (attempt > 0) {
          // Exponential backoff delay
          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
          await this.sleep(delay);
          console.log(`[ImageGen] Retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
        }

        const result = await this.makeRequest(description, options);
        return result;
      } catch (error) {
        lastError = error as Error;
        console.error(`[ImageGen] Attempt ${attempt + 1} failed:`, error);

        // Don't retry on certain errors
        if (this.isNonRetryableError(error)) {
          break;
        }
      }
    }

    // All retries failed
    return {
      success: false,
      error: 'GENERATION_FAILED',
      message: 'Unable to generate image. Please try again later.',
    };
  }

  /**
   * Generates a fitting model image using a reference image for face-matching.
   * Uses OpenRouter's multimodal content format to pass the reference image.
   *
   * @param prompt - Fitting model generation prompt with style requirements
   * @param referenceImageBase64 - Base64 encoded reference image (with data URL prefix)
   * @returns Promise resolving to image generation response
   *
   * @example
   * const client = new OpenRouterImageClient(apiKey);
   * const response = await client.generateFittingModelImage(
   *   "Create a photorealistic fitting model...",
   *   "data:image/jpeg;base64,/9j/4AAQ..."
   * );
   */
  async generateFittingModelImage(
    prompt: string,
    referenceImageBase64: string
  ): Promise<ImageGenerationResponse> {
    // Validate inputs
    if (!prompt || typeof prompt !== 'string' || prompt.trim() === '') {
      return {
        success: false,
        error: 'INVALID_PROMPT',
        message: 'Fitting model prompt is required',
      };
    }

    if (!referenceImageBase64 || typeof referenceImageBase64 !== 'string' || referenceImageBase64.trim() === '') {
      return {
        success: false,
        error: 'INVALID_REFERENCE_IMAGE',
        message: 'Reference image is required for fitting model generation',
      };
    }

    if (!referenceImageBase64.startsWith('data:image/')) {
      return {
        success: false,
        error: 'INVALID_REFERENCE_IMAGE_FORMAT',
        message: 'Reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
      };
    }

    // Check client-side rate limiting
    if (!this.checkRateLimit()) {
      return {
        success: false,
        error: 'RATE_LIMITED',
        message: 'Too many requests. Please wait a moment before trying again.',
      };
    }

    // Attempt generation with retries
    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
      try {
        if (attempt > 0) {
          // Exponential backoff delay
          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
          await this.sleep(delay);
          console.log(`[ImageGen] Fitting model retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
        }

        const result = await this.makeFittingModelRequest(prompt, referenceImageBase64);
        return result;
      } catch (error) {
        lastError = error as Error;
        console.error(`[ImageGen] Fitting model attempt ${attempt + 1} failed:`, error);

        // Don't retry on certain errors
        if (this.isNonRetryableError(error)) {
          break;
        }
      }
    }

    // All retries failed
    return {
      success: false,
      error: 'GENERATION_FAILED',
      message: 'Unable to generate fitting model image. Please try again later.',
    };
  }

  /**
   * Makes multimodal API request to OpenRouter for fitting model generation
   *
   * @private
   */
  private async makeFittingModelRequest(
    prompt: string,
    referenceImageBase64: string
  ): Promise<ImageGenerationResponse> {
    // Build multimodal request body with text + image content
    // OpenRouter expects text first, then images (per documentation)
    const requestBody = {
      model: OPENROUTER_CONFIG.model,
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: prompt,
            },
            {
              type: 'image_url',
              image_url: {
                url: referenceImageBase64,
              },
            },
          ],
        },
      ],
      modalities: ['text', 'image'], // Required for image generation output
      max_tokens: 4096,
    };

    console.log('[ImageGen] Sending fitting model request to OpenRouter:', {
      model: requestBody.model,
      promptLength: prompt.length,
      hasReferenceImage: true,
    });

    // Create abort controller with extended timeout for fitting model
    const controller = new AbortController();
    const timeoutId = setTimeout(
      () => controller.abort(),
      OpenRouterImageClient.FITTING_MODEL_CONFIG.timeout
    );

    try {
      const response = await fetch(`${OPENROUTER_CONFIG.baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${this.apiKey}`,
          'HTTP-Referer': 'https://ootday.com',
          'X-Title': 'OOTDay Fashion Assistant',
        },
        body: JSON.stringify(requestBody),
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          `OpenRouter API error: ${response.status} - ${errorData.error?.message || response.statusText}`
        );
      }

      const data = await response.json();

      // Parse response and extract image using existing method
      const imageData = this.parseImageResponse(data);

      return {
        success: true,
        imageBase64: imageData.base64,
        imageUrl: imageData.url,
        metadata: {
          model: OPENROUTER_CONFIG.model,
          generatedAt: new Date().toISOString(),
          prompt: prompt,
        },
        message: 'Fitting model image generated successfully',
      };
    } catch (error) {
      clearTimeout(timeoutId);

      if (error instanceof Error) {
        if (error.name === 'AbortError') {
          throw new Error('Request timeout - fitting model generation took too long');
        }
        throw error;
      }

      throw new Error('Unknown error during fitting model generation');
    }
  }

  /**
   * Makes the actual API request to OpenRouter
   *
   * @private
   */
  private async makeRequest(
    description: string,
    options?: ImageGenerationRequest['style']
  ): Promise<ImageGenerationResponse> {
    // Build fashion-specific prompt
    const prompt = this.buildFashionPrompt(description, options);

    // Create request payload - OpenRouter image generation requires messages format with modalities
    const requestBody = {
      model: OPENROUTER_CONFIG.model,
      messages: [
        {
          role: 'user',
          content: prompt,
        },
      ],
      modalities: ['text', 'image'], // Required for image generation
      max_tokens: 4096, // For image generation
    };

    console.log('[ImageGen] Sending request to OpenRouter:', {
      model: requestBody.model,
      promptLength: prompt.length,
    });

    // Create abort controller for timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), OPENROUTER_CONFIG.timeout);

    try {
      const response = await fetch(`${OPENROUTER_CONFIG.baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${this.apiKey}`,
          'HTTP-Referer': 'https://ootday.com', // Optional: Your site URL
          'X-Title': 'OOTDay Fashion Assistant', // Optional: Your app name
        },
        body: JSON.stringify(requestBody),
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          `OpenRouter API error: ${response.status} - ${errorData.error?.message || response.statusText}`
        );
      }

      const data = await response.json();

      // Parse response and extract image
      // Note: Gemini 2.5 Flash Preview returns image as base64 in content
      const imageData = this.parseImageResponse(data);

      return {
        success: true,
        imageBase64: imageData.base64,
        imageUrl: imageData.url,
        metadata: {
          model: OPENROUTER_CONFIG.model,
          generatedAt: new Date().toISOString(),
          prompt: prompt,
        },
        message: 'Image generated successfully',
      };
    } catch (error) {
      clearTimeout(timeoutId);

      if (error instanceof Error) {
        if (error.name === 'AbortError') {
          throw new Error('Request timeout - image generation took too long');
        }
        throw error;
      }

      throw new Error('Unknown error during image generation');
    }
  }

  /**
   * Builds fashion-specific prompt for image generation
   * Applies professional photography style and Thai fashion aesthetic
   *
   * @private
   */
  private buildFashionPrompt(
    description: string,
    options?: ImageGenerationRequest['style']
  ): string {
    const photographyStyle = options?.photographyStyle || 'editorial fashion';
    const composition = options?.composition || 'full-body model shoot';
    const lighting = options?.lighting || 'studio';
    const aesthetic = options?.aestheticContext || 'modern international';

    // Fashion-specific prompt template
    const promptTemplate = `
Generate a high-quality fashion photograph of a real person wearing the outfit:

OUTFIT DESCRIPTION: ${description}

PHOTOGRAPHY STYLE: ${photographyStyle}
COMPOSITION: ${composition}
LIGHTING: ${lighting}
AESTHETIC: ${aesthetic} fashion style

REQUIREMENTS:
- Professional product photography quality
- Clear, well-lit composition
- Clean background (white or minimal)
- Sharp focus on outfit details
- Accurate color representation
- Suitable for fashion e-commerce
- Thai contemporary fashion aesthetic
- Elegant and modern presentation

AVOID:
- Blurry or low-resolution images
- Cluttered backgrounds
- Poor lighting or shadows
- Distorted proportions
- Unrealistic colors
`.trim();

    return promptTemplate;
  }

  /**
   * Parses image response from OpenRouter API
   * OpenRouter returns images in an 'images' array within the assistant message
   *
   * @private
   */
  private parseImageResponse(data: any): { base64?: string; url?: string } {
    // OpenRouter returns images as base64 data URLs in the 'images' array
    // Format: { choices: [{ message: { content: "...", images: ["data:image/png;base64,..."] } }] }

    try {
      console.log('[ImageGen] Parsing response:', JSON.stringify(data).slice(0, 500));

      if (data.choices && data.choices[0] && data.choices[0].message) {
        const message = data.choices[0].message;

        // Primary format: images array (OpenRouter standard)
        if (message.images && Array.isArray(message.images) && message.images.length > 0) {
          const imageData = message.images[0];
          console.log('[ImageGen] Found image in images array, type:', typeof imageData);

          // Images are returned as data URLs (data:image/png;base64,...)
          if (typeof imageData === 'string' && imageData.startsWith('data:image')) {
            return { base64: imageData };
          }

          // Or as object with nested structure: {"type":"image_url","image_url":{"url":"data:..."}}
          if (typeof imageData === 'object') {
            // Check for image_url.url format (OpenRouter Gemini format)
            if (imageData.image_url?.url) {
              console.log('[ImageGen] Found image in image_url.url format');
              const url = imageData.image_url.url;
              if (url.startsWith('data:image')) {
                return { base64: url };
              }
              return { url };
            }
            // Check for b64_json format
            if (imageData.b64_json) {
              return { base64: `data:image/png;base64,${imageData.b64_json}` };
            }
            // Check for direct base64/url
            if (imageData.base64) {
              return { base64: imageData.base64.startsWith('data:') ? imageData.base64 : `data:image/png;base64,${imageData.base64}` };
            }
            if (imageData.url) {
              return { url: imageData.url };
            }
          }
        }

        // Check content for embedded base64 or URLs
        const content = message.content;
        if (typeof content === 'string') {
          // Check if content contains base64 image data
          const base64Match = content.match(/data:image\/(png|jpeg|jpg|webp);base64,[A-Za-z0-9+/=]+/);
          if (base64Match) {
            console.log('[ImageGen] Found base64 image in content');
            return { base64: base64Match[0] };
          }

          // Check for URL in content
          const urlMatch = content.match(/(https?:\/\/[^\s<>"]+\.(png|jpg|jpeg|gif|webp))/i);
          if (urlMatch) {
            console.log('[ImageGen] Found URL in content');
            return { url: urlMatch[0] };
          }
        }

        // Check for structured image data (fallback)
        if (message.image) {
          console.log('[ImageGen] Found image in message.image');
          return {
            base64: message.image.base64 || (message.image.b64_json ? `data:image/png;base64,${message.image.b64_json}` : undefined),
            url: message.image.url,
          };
        }
      }

      // Fallback: return empty (will need to handle in caller)
      console.warn('[ImageGen] Could not parse image from response. Keys:', Object.keys(data));
      if (data.choices?.[0]?.message) {
        console.warn('[ImageGen] Message keys:', Object.keys(data.choices[0].message));
      }
      return {};
    } catch (error) {
      console.error('[ImageGen] Error parsing image response:', error);
      return {};
    }
  }

  /**
   * Client-side rate limiting check
   * Limits to approximately 10 requests per minute
   *
   * @private
   */
  private checkRateLimit(): boolean {
    const now = Date.now();
    const minuteAgo = now - 60000;

    // Reset counter if a minute has passed
    if (this.lastRequestTime < minuteAgo) {
      this.requestCount = 0;
    }

    // Check if under limit
    if (this.requestCount >= 10) {
      return false;
    }

    // Update counters
    this.requestCount++;
    this.lastRequestTime = now;

    return true;
  }

  /**
   * Checks if error is non-retryable (auth, validation, etc.)
   *
   * @private
   */
  private isNonRetryableError(error: any): boolean {
    if (!error) return false;

    const errorMessage = error.message || error.toString();

    // Don't retry authentication errors
    if (errorMessage.includes('401') || errorMessage.includes('403')) {
      return true;
    }

    // Don't retry validation errors
    if (errorMessage.includes('400') || errorMessage.includes('INVALID')) {
      return true;
    }

    // Don't retry rate limit errors (need to wait)
    if (errorMessage.includes('429') || errorMessage.includes('RATE_LIMIT')) {
      return true;
    }

    return false;
  }

  /**
   * Sleep utility for retry delays
   *
   * @private
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

/**
 * Creates a new OpenRouter image client with API key from environment
 *
 * @returns OpenRouterImageClient instance or null if API key not available
 *
 * @example
 * const client = createImageClient();
 * if (client) {
 *   const response = await client.generateOutfitImage(description);
 * }
 */
export function createImageClient(): OpenRouterImageClient | null {
  const apiKey = process.env.OPENROUTER_API_KEY;

  if (!apiKey) {
    console.warn('[ImageGen] OPENROUTER_API_KEY not found in environment');
    return null;
  }

  try {
    return new OpenRouterImageClient(apiKey);
  } catch (error) {
    console.error('[ImageGen] Failed to create image client:', error);
    return null;
  }
}

'use client'

import { useState, useEffect } from 'react'
import { ChatHeader } from './ChatHeader'
import { ChatMessage } from './ChatMessage'
import { ChatInput } from './ChatInput'
import { QuickPrompts } from './QuickPrompts'
import { OutfitRecommendationCard } from './OutfitRecommendationCard'
import { InteractiveTestMode } from './InteractiveTestMode'
import { Button } from '@/components/ui/button'
import { PanelSizeControls } from '@/components/layout/PanelSizeControls'
import { useResizablePanelContext } from '@/components/layout/ResizablePanel'
import { Beaker } from 'lucide-react'
import type { ChatMessage as ChatMessageType, Outfit } from '@/lib/types'
import type { TestResult } from '@/lib/types/test-types'
import { getMockOutfitResponse } from '@/lib/mock-data'
import { exportResultsBoth } from '@/lib/test-result-exporter'
import type { SessionContext } from '@/lib/types/chat-types'
import { createSessionContext } from '@/lib/utils/session-context'
import { useUserProfile } from '@/lib/hooks/useUserProfile'

interface ChatAssistantProps {
  onViewOutfit: (outfit: Outfit) => void
}

export function ChatAssistant({ onViewOutfit }: ChatAssistantProps) {
  const [messages, setMessages] = useState<ChatMessageType[]>([])
  const [isTyping, setIsTyping] = useState(false)
  const [testMode, setTestMode] = useState(false)

  // v2.0: Session context for duplicate prevention
  const [sessionContext, setSessionContext] = useState<SessionContext>(() => createSessionContext())
  const [conversationId] = useState<string>(() => `conv-${Date.now()}`)

  // v2.4: User profile for gender preference
  const { profile } = useUserProfile()

  // v3.1: Image generation state (Customer Journey Step 4)
  const [generatingImage, setGeneratingImage] = useState(false)
  const [imageGenerationError, setImageGenerationError] = useState<string | null>(null)

  // v3.2: Initialize with Thai greeting message
  useEffect(() => {
    if (messages.length === 0) {
      const greeting: ChatMessageType = {
        id: 'greeting-initial',
        content: 'ฮ้ายฮายย👋 กำลังหาชุดไปไหนอยู่น้าา',
        sender: 'assistant',
        timestamp: new Date(),
      }
      setMessages([greeting])
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Get resize controls from ResizablePanel context (optional - only if in resizable panel)
  let panelWidth = 420
  let setPresetSize: ((size: number) => void) | undefined
  try {
    const context = useResizablePanelContext()
    panelWidth = context.panelWidth
    setPresetSize = context.setPresetSize
  } catch {
    // Not in a resizable panel context, that's okay
  }

  const isTestModeEnabled = process.env.NEXT_PUBLIC_ENABLE_TEST_MODE === 'true'

  const handleTestComplete = (result: TestResult) => {
    console.log('Test completed:', result)
  }

  const handleExportResults = (results: TestResult[]) => {
    exportResultsBoth(results)
  }

  const handleSendMessage = async (content: string) => {
    if (!content.trim()) return

    // Add user message
    const userMessage: ChatMessageType = {
      id: `user-${Date.now()}`,
      content: content.trim(),
      sender: 'user',
      timestamp: new Date(),
    }

    setMessages((prev) => [...prev, userMessage])
    setIsTyping(true)

    try {
      // Call real chat API
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: content.trim(),
          conversationHistory: messages.map((msg) => ({
            role: msg.sender === 'user' ? 'user' : 'assistant',
            content: msg.content,
          })),
          sessionContext, // v2.0: Send current session context
          conversationId, // v2.0: Send conversation ID
          userPreferences: {
            gender: profile?.gender as 'men' | 'women' | undefined,
            userName: profile?.userName,
            ageRange: profile?.ageRange,
            stylePreferences: profile?.stylePreferences,
          }, // v2.5: Pass detailed profile info
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to get response from chat API')
      }

      const data = await response.json()

      // v2.0: Update session context if returned
      if (data.sessionContext) {
        setSessionContext(data.sessionContext)
        console.log(`[Chat] Session updated: ${data.sessionContext.recommendedProductIds?.length || 0} total products recommended`)
      }

      // Create AI response message (normal flow)
      const aiResponse: ChatMessageType = {
        id: `ai-${Date.now()}`,
        content: data.message || 'สวัสดีค่ะ! นี่คือคำแนะนำสำหรับคุณ',
        sender: 'assistant',
        timestamp: new Date(),
        outfits: data.outfits || [],
      }

      setMessages((prev) => [...prev, aiResponse])
      setIsTyping(false)

      // v3.1: Check if this is an image generation request (Auto or Manual)
      if (data.imageRequest && data.outfitDescription) {
        console.log('[Chat] Image request detected, generating image...')

        // Add AI acknowledgment message for auto-generation (UX Feedback)
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ Looks Inspire จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        // Generate image
        setGeneratingImage(true)
        setImageGenerationError(null)

        try {
          const imageResponse = await fetch('/api/generate-image', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              description: data.outfitDescription,
            }),
          })

          const imageData = await imageResponse.json()

          if (imageData.success && (imageData.imageUrl || imageData.imageBase64)) {
            // Determine UI Description (Thai)
            const uiDescription = (data.outfits && data.outfits.length > 0)
              ? data.outfits[0].description
              : "ภาพตัวอย่าง Looks Inspire จากชุดที่แนะนำ ✨";

            const imageMessage: ChatMessageType = {
              id: `ai-image-${Date.now()}`,
              content: 'นี่คือภาพชุดที่เราคิด! ✨',
              sender: 'assistant',
              timestamp: new Date(),
              imageUrl: imageData.imageUrl,
              imageBase64: imageData.imageBase64,
              outfitDescription: uiDescription, // Use Thai Description for UI
            }
            setMessages((prev) => [...prev, imageMessage])
          } else {
            // Image generation failed
            setImageGenerationError(imageData.message || 'ไม่สามารถสร้างภาพได้ กรุณาลองใหม่อีกครั้ง')

            // Only show error message if it was an explicit request (optional, here we show small error)
            const errorMessage: ChatMessageType = {
              id: `ai-error-${Date.now()}`,
              content: `ขออภัยค่ะ ${imageData.message || 'ไม่สามารถสร้างภาพได้ กรุณาลองใหม่อีกครั้ง'} 😊`,
              sender: 'assistant',
              timestamp: new Date(),
            }
            setMessages((prev) => [...prev, errorMessage])
          }
        } catch (error) {
          console.error('[Chat] Image generation error:', error)
          setImageGenerationError('เกิดข้อผิดพลาดในการสร้างภาพ')

          const errorMessage: ChatMessageType = {
            id: `ai-error-${Date.now()}`,
            content: 'ขออภัยค่ะ เกิดข้อผิดพลาดในการสร้างภาพ ลองใหม่อีกครั้งได้นะคะ 😊',
            sender: 'assistant',
            timestamp: new Date(),
          }
          setMessages((prev) => [...prev, errorMessage])
        } finally {
          setGeneratingImage(false)
        }
      }
    } catch (error) {
      console.error('Chat error:', error)

      // Fallback to mock response on error
      const aiResponse = getMockOutfitResponse(content)
      setMessages((prev) => [...prev, aiResponse])
      setIsTyping(false)

      // v3.2: Auto-trigger image generation for Mock/Fallback responses
      if (aiResponse.outfits && aiResponse.outfits.length > 0) {
        console.log('[Chat] Fallback: Auto-generating image for mock response...')

        // Add acknowledgement
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ Looks Inspire จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        // Trigger generation
        setGeneratingImage(true)
        setImageGenerationError(null)

        try {
          // Generate description from the first outfit/products
          const distinctProducts = aiResponse.outfits[0].items.slice(0, 3)
          const productDesc = distinctProducts.map(p => (p as any).visualDescription || p.name).join(', ')
          const desc = `Fashion outfit usage: ${productDesc}. Style: Professional fashion model.`

          const imageResponse = await fetch('/api/generate-image', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ description: desc }),
          })

          const imageData = await imageResponse.json()

          // Determine UI Description (Thai) from fallback response
          const uiDescription = (aiResponse.outfits && aiResponse.outfits.length > 0)
            ? aiResponse.outfits[0].description
            : "ภาพตัวอย่าง Looks Inspire จากชุดที่แนะนำ ✨";

          if (imageData.success && (imageData.imageUrl || imageData.imageBase64)) {
            const imageMessage: ChatMessageType = {
              id: `ai-image-${Date.now()}`,
              content: 'นี่คือภาพชุดที่เราคิด! ✨',
              sender: 'assistant',
              timestamp: new Date(),
              imageUrl: imageData.imageUrl,
              imageBase64: imageData.imageBase64,
              outfitDescription: uiDescription, // Use Thai Description for UI
            }
            setMessages((prev) => [...prev, imageMessage])
          } else {
            setImageGenerationError(imageData.message || 'Image generation failed')
            const errorMessage: ChatMessageType = {
              id: `ai-error-${Date.now()}`,
              content: `ขออภัยค่ะ ${imageData.message || 'ไม่สามารถสร้างภาพได้ (Mock Mode)'} 😊`,
              sender: 'assistant',
              timestamp: new Date(),
            }
            setMessages((prev) => [...prev, errorMessage])
          }
        } catch (err) {
          console.error('Fallback Image Gen Error:', err)
          setImageGenerationError('Failed to generate image')
          const errorMessage: ChatMessageType = {
            id: `ai-error-${Date.now()}`,
            content: 'ขออภัยค่ะ ไม่สามารถเชื่อมต่อกับบริการสร้างภาพได้',
            sender: 'assistant',
            timestamp: new Date(),
          }
          setMessages((prev) => [...prev, errorMessage])
        } finally {
          setGeneratingImage(false)
        }
      }
    }
  }

  return (
    <div className="h-full flex flex-col">
      {/* Test Mode Header */}
      {isTestModeEnabled && (
        <div className={`border-b px-4 py-3 flex items-center justify-between ${testMode ? 'bg-orange-50' : ''}`}>
          <div className="flex items-center gap-2">
            {testMode && (
              <span className="px-3 py-1 bg-orange-500 text-white font-bold rounded-md text-sm flex items-center gap-1">
                <Beaker className="w-4 h-4" />
                TEST MODE
              </span>
            )}
            <span className="text-sm text-muted-foreground">
              {testMode ? 'LLM Model Testing Interface' : 'OOTDay Stylist'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
            <Button
              size="sm"
              variant={testMode ? "primary" : "outline"}
              onClick={() => setTestMode(!testMode)}
              className={testMode ? "bg-orange-600 hover:bg-orange-700" : ""}
            >
              <Beaker className="w-4 h-4 mr-2" />
              {testMode ? 'Exit Test Mode' : 'Test Mode'}
            </Button>
          </div>
        </div>
      )}

      {/* Regular Header with resize controls */}
      {!isTestModeEnabled && !testMode && (
        <div className="border-b px-4 py-3 flex items-center justify-between">
          <span className="text-sm font-medium">OOTDay Stylist</span>
          {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
        </div>
      )}

      {/* Interactive Test Mode - Full Screen */}
      {testMode && isTestModeEnabled && (
        <div className="flex-1 overflow-hidden">
          <InteractiveTestMode onExport={handleExportResults} />
        </div>
      )}

      {!testMode && <ChatHeader />}

      {/* Messages Area */}
      {!testMode && (
        <div className="flex-1 overflow-y-auto px-4 py-3">
          {messages.length === 0 && (
            <div className="text-center py-8">
              <p className="text-sm text-muted-foreground leading-relaxed max-w-xs mx-auto">
                สวัสดีค่ะ! OOTDay Stylist พร้อมช่วยหาลุคที่ใช่สำหรับคุณค่ะ ✨
              </p>
            </div>
          )}

          {messages.map((message) => (
            <div key={message.id}>
              <ChatMessage message={message} />

              {/* Outfit recommendations */}
              {message.outfits && message.outfits.length > 0 && (
                <div className="ml-10 mt-2 space-y-2">
                  {message.outfits.map((outfit) => (
                    <OutfitRecommendationCard
                      key={outfit.id}
                      outfit={outfit}
                      onViewOutfit={onViewOutfit}
                    />
                  ))}
                </div>
              )}
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start">
              <div className="flex items-center gap-2 bg-gray-100 rounded-lg px-3 py-2">
                <div className="flex space-x-1">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Quick Prompts */}
      {!testMode && <QuickPrompts onPromptClick={handleSendMessage} />}

      {/* Chat Input */}
      {!testMode && <ChatInput onSend={handleSendMessage} disabled={isTyping} />}
    </div>
  )
}

