     1→/**
     2→ * Chat Types for System Prompt Enhancement
     3→ *
     4→ * TypeScript interfaces for session management, clarification logic,
     5→ * and conversation context tracking.
     6→ *
     7→ * Related PRD: 0006-prd-system-prompt-enhancement-guardrails.md
     8→ */
     9→
    10→/**
    11→ * Dialogue Phase
    12→ * Tracks current phase of conversation to prevent loops
    13→ * Related: tasks-0006-prd-system-prompt-enhancement-guardrails-LOOP-FIX.md (Sub-task 9.9)
    14→ */
    15→export type DialoguePhase = 'clarification' | 'recommendation' | 'follow-up';
    16→
    17→/**
    18→ * Clarification Type
    19→ * Types of clarifications that can be asked
    20→ */
    21→export type ClarificationType = 'gender' | 'occasion' | 'destination' | 'budget';
    22→
    23→/**
    24→ * User Profile for Personalized Recommendations (v3.0 - RAG Integration)
    25→ * Captures user preferences for RAG-based retrieval filtering
    26→ */
    27→export interface UserProfile {
    28→  /** User's style preferences (e.g., 'minimal', 'casual', 'elegant') */
    29→  stylePreferences?: string[];
    30→  /** User's body type for styling advice */
    31→  bodyType?: 'hourglass' | 'pear' | 'apple' | 'rectangle' | 'invertedTriangle';
    32→  /** Preferred colors */
    33→  colorPreferences?: string[];
    34→  /** Budget tier for recommendations */
    35→  budgetTier?: 'budget' | 'mid-range' | 'premium' | 'luxury';
    36→}
    37→
    38→/**
    39→ * Session Context for Duplicate Prevention
    40→ * Tracks products recommended during the current chat session
    41→ * Enhanced with loop prevention tracking (v2.1)
    42→ * Enhanced with RAG integration (v3.0)
    43→ */
    44→export interface SessionContext {
    45→  /** Array of product SKUs/IDs already recommended in this session */
    46→  recommendedProductIds: string[];
    47→  /** Optional session identifier for tracking */
    48→  sessionId?: string;
    49→  /** Timestamp when session was created */
    50→  createdAt?: Date;
    51→  /** Track which clarifications have been asked to prevent loops (Array for JSON serialization) */
    52→  askedClarifications: ClarificationType[];
    53→  /** Extracted information from conversation history */
    54→  conversationContext: {
    55→    gender?: 'men' | 'women';
    56→    occasion?: string;
    57→    destination?: string;
    58→    budget?: number;
    59→  };
    60→  /**
    61→   * Current dialogue phase (v2.1 - Loop Prevention)
    62→   * - 'clarification': Asking questions (max 2)
    63→   * - 'recommendation': Providing outfit/tips
    64→   * - 'follow-up': Handling adjustments/refinements
    65→   */
    66→  dialoguePhase?: DialoguePhase;
    67→  /**
    68→   * Count of clarification turns (v2.1 - Loop Prevention)
    69→   * Used to enforce MAX 2 clarifications rule
    70→   */
    71→  clarificationTurnCount?: number;
    72→  /**
    73→   * Flag indicating recommendations have been provided (v2.2 - Step 3 & 4)
    74→   * Critical for POST-RECOMMENDATION LOCKOUT enforcement
