     1→/**
     2→ * Image Generation API Route
     3→ * POST /api/generate-image
     4→ *
     5→ * Handles outfit image generation requests using OpenRouter's Gemini 2.5 Flash Preview model
     6→ *
     7→ * Features:
     8→ * - Server-side rate limiting (10 requests per minute per IP)
     9→ * - Request validation
    10→ * - Error handling with appropriate HTTP status codes
    11→ * - Logging for debugging
    12→ */
    13→
    14→import { NextRequest, NextResponse } from 'next/server';
    15→import { OpenRouterImageClient } from '@/lib/services/image-generation-service';
    16→import type { ImageGenerationRequest } from '@/lib/types/image-types';
    17→import fs from 'fs';
    18→import path from 'path';
    19→import { spawn } from 'child_process';
    20→
    21→/**
    22→ * Rate limiting configuration
    23→ * Tracks request counts per IP address
    24→ */
    25→const rateLimitMap = new Map<string, { count: number; resetTime: number }>();
    26→const RATE_LIMIT_WINDOW = 60000; // 1 minute in milliseconds
    27→const RATE_LIMIT_MAX_REQUESTS = 10;
    28→
    29→/**
    30→ * Checks if request is rate limited
    31→ *
    32→ * @param ip - Client IP address
    33→ * @returns true if rate limited, false if allowed
    34→ */
    35→function isRateLimited(ip: string): boolean {
    36→  const now = Date.now();
    37→  const record = rateLimitMap.get(ip);
    38→
    39→  // No record or window expired - create new record
    40→  if (!record || now > record.resetTime) {
    41→    rateLimitMap.set(ip, {
    42→      count: 1,
    43→      resetTime: now + RATE_LIMIT_WINDOW,
    44→    });
    45→    return false;
    46→  }
    47→
    48→  // Increment count
    49→  record.count++;
    50→
    51→  // Check if over limit
    52→  if (record.count > RATE_LIMIT_MAX_REQUESTS) {
    53→    return true;
    54→  }
    55→
    56→  return false;
    57→}
    58→
    59→/**
    60→ * Gets client IP address from request
    61→ *
    62→ * @param request - Next.js request object
    63→ * @returns IP address string
    64→ */
    65→function getClientIP(request: NextRequest): string {
    66→  // Try various headers that might contain the real IP
    67→  const forwarded = request.headers.get('x-forwarded-for');
    68→  if (forwarded) {
    69→    return forwarded.split(',')[0].trim();
    70→  }
    71→
    72→  const realIP = request.headers.get('x-real-ip');
    73→  if (realIP) {
    74→    return realIP;
    75→  }
    76→
    77→  // Fallback to a default value
    78→  return 'unknown';
    79→}
    80→
    81→/**
    82→ * Ensures a directory exists, creating it if necessary
    83→ *
    84→ * @param dirPath - Absolute path to the directory
    85→ */
    86→function ensureDirectoryExists(dirPath: string): void {
    87→  if (!fs.existsSync(dirPath)) {
    88→    fs.mkdirSync(dirPath, { recursive: true });
    89→    console.log('[API] Created directory:', dirPath);
    90→  }
    91→}
    92→
    93→/**
    94→ * Generates a unique filename for an outfit image
    95→ *
    96→ * @returns Filename in format: outfit-{timestamp}.png
    97→ */
    98→function generateImageFilename(): string {
    99→  const timestamp = Date.now();
   100→  return `outfit-${timestamp}.png`;
   101→}
   102→
   103→/**
   104→ * Removes background from an image file using rembg Python script
   105→ *
   106→ * @param inputPath - Absolute path to the input image
   107→ * @param outputPath - Absolute path to save the output image
   108→ * @returns Promise that resolves to true on success, false on failure
   109→ */
   110→async function removeBackgroundFromFile(inputPath: string, outputPath: string): Promise<boolean> {
   111→  return new Promise((resolve) => {
   112→    const scriptPath = path.join(process.cwd(), '..', '..', 'scripts', 'image_processing', 'remove_bg_rembg.py');
   113→
   114→    console.log('[API] Running background removal:', { inputPath, outputPath, scriptPath });
   115→
   116→    const python = spawn('python3', [scriptPath, inputPath, outputPath]);
   117→
   118→    let stderr = '';
   119→
   120→    python.stderr.on('data', (data) => {
   121→      stderr += data.toString();
   122→      console.log('[API] Background removal:', data.toString().trim());
   123→    });
   124→
   125→    python.on('close', (code) => {
   126→      if (code === 0) {
   127→        console.log('[API] Background removal completed successfully');
   128→        resolve(true);
   129→      } else {
   130→        console.error('[API] Background removal failed with code:', code);
   131→        console.error('[API] stderr:', stderr);
   132→        resolve(false);
   133→      }
   134→    });
   135→
   136→    python.on('error', (err) => {
   137→      console.error('[API] Failed to spawn background removal process:', err);
   138→      resolve(false);
   139→    });
   140→  });
   141→}
   142→
   143→/**
   144→ * Saves a base64-encoded image to disk as a PNG file
   145→ *
   146→ * @param base64Data - Base64 image data (with or without data URL prefix)
   147→ * @param filename - Name of the file to save
   148→ * @returns Relative public URL path to the saved image
   149→ * @throws Error if file save fails
   150→ */
   151→function saveBase64Image(base64Data: string, filename: string): string {
   152→  // Strip data URL prefix if present (e.g., "data:image/png;base64,")
   153→  const base64Content = base64Data.includes(',')
   154→    ? base64Data.split(',')[1]
   155→    : base64Data;
   156→
   157→  // Construct absolute path to the public/generated-images directory
   158→  const publicDir = path.join(process.cwd(), 'public', 'generated-images');
   159→  ensureDirectoryExists(publicDir);
   160→
   161→  const filePath = path.join(publicDir, filename);
   162→
   163→  // Convert base64 to buffer and write to file
   164→  const imageBuffer = Buffer.from(base64Content, 'base64');
   165→  fs.writeFileSync(filePath, imageBuffer);
   166→
   167→  console.log('[API] Saved image to:', filePath);
   168→
   169→  // Return public URL path (relative)
   170→  return `/generated-images/${filename}`;
   171→}
   172→
   173→/**
   174→ * POST handler for image generation
   175→ *
   176→ * Request body:
   177→ * {
   178→ *   description: string,
   179→ *   style?: {
   180→ *     photographyStyle?: string,
   181→ *     composition?: string,
   182→ *     lighting?: string,
   183→ *     aestheticContext?: string
   184→ *   }
   185→ * }
   186→ *
   187→ * Response on success:
   188→ * {
   189→ *   success: true,
   190→ *   imageUrl: string,        // Public URL path (e.g., /generated-images/outfit-1732800000000.png)
   191→ *   imageBase64: string,      // Base64-encoded image data
   192→ *   error?: undefined,
   193→ *   message?: undefined
   194→ * }
   195→ *
   196→ * Response on failure:
   197→ * {
   198→ *   success: false,
   199→ *   imageUrl?: undefined,
   200→ *   imageBase64?: undefined,
   201→ *   error: string,
   202→ *   message: string
   203→ * }
   204→ */
   205→export async function POST(request: NextRequest) {
   206→  const startTime = Date.now();
   207→
   208→  try {
   209→    // Get client IP for rate limiting
   210→    const clientIP = getClientIP(request);
   211→
   212→    console.log('[API] Image generation request received from IP:', clientIP);
   213→
   214→    // Check rate limiting
   215→    if (isRateLimited(clientIP)) {
   216→      console.warn('[API] Rate limit exceeded for IP:', clientIP);
   217→      return NextResponse.json(
   218→        {
   219→          success: false,
   220→          error: 'RATE_LIMITED',
   221→          message: 'Too many requests. Please wait a minute before trying again.',
   222→        },
   223→        {
   224→          status: 429,
   225→          headers: {
   226→            'Retry-After': '60',
   227→          },
   228→        }
   229→      );
   230→    }
   231→
   232→    // Check if OPENROUTER_API_KEY is configured
   233→    const apiKey = process.env.OPENROUTER_API_KEY;
   234→    if (!apiKey) {
   235→      console.error('[API] OPENROUTER_API_KEY not configured');
   236→      return NextResponse.json(
   237→        {
   238→          success: false,
   239→          error: 'SERVICE_UNAVAILABLE',
   240→          message: 'Image generation service is not configured. Please contact support.',
   241→        },
   242→        { status: 503 }
   243→      );
   244→    }
   245→
   246→    // Parse request body
   247→    let body: ImageGenerationRequest;
   248→    try {
   249→      body = await request.json();
   250→    } catch (error) {
   251→      console.error('[API] Invalid JSON in request body:', error);
   252→      return NextResponse.json(
   253→        {
   254→          success: false,
   255→          error: 'INVALID_REQUEST',
   256→          message: 'Invalid request format',
   257→        },
   258→        { status: 400 }
   259→      );
   260→    }
   261→
   262→    // Validate request body
   263→    const { description, style, referenceImage, generationType } = body;
   264→
   265→    if (!description || typeof description !== 'string' || description.trim() === '') {
   266→      console.error('[API] Missing or invalid description');
   267→      return NextResponse.json(
   268→        {
   269→          success: false,
   270→          error: 'INVALID_DESCRIPTION',
   271→          message: 'Outfit description is required',
   272→        },
   273→        { status: 400 }
   274→      );
   275→    }
   276→
   277→    // Validate description length (3000 chars for fitting-model, 1000 for outfit)
   278→    const maxDescriptionLength = generationType === 'fitting-model' ? 3000 : 1000;
   279→    if (description.length > maxDescriptionLength) {
   280→      console.error('[API] Description too long:', description.length);
   281→      return NextResponse.json(
   282→        {
   283→          success: false,
   284→          error: 'DESCRIPTION_TOO_LONG',
   285→          message: `Description is too long. Please keep it under ${maxDescriptionLength} characters.`,
   286→        },
   287→        { status: 400 }
   288→      );
   289→    }
   290→
   291→    // Validate referenceImage format when provided with fitting-model generation
   292→    if (generationType === 'fitting-model' && referenceImage) {
   293→      if (typeof referenceImage !== 'string' || referenceImage.trim() === '') {
   294→        console.error('[API] Invalid reference image for fitting-model generation');
   295→        return NextResponse.json(
   296→          {
   297→            success: false,
   298→            error: 'INVALID_REFERENCE_IMAGE',
   299→            message: 'Reference image must be a valid string',
   300→          },
   301→          { status: 400 }
   302→        );
   303→      }
   304→
   305→      if (!referenceImage.startsWith('data:image/')) {
   306→        console.error('[API] Invalid reference image format');
   307→        return NextResponse.json(
   308→          {
   309→            success: false,
   310→            error: 'INVALID_REFERENCE_IMAGE_FORMAT',
   311→            message: 'Reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
   312→          },
   313→          { status: 400 }
   314→        );
   315→      }
   316→    }
   317→
   318→    console.log('[API] Generating image:', {
   319→      descriptionLength: description.length,
   320→      style: style || 'default',
   321→      generationType: generationType || 'outfit',
   322→      hasReferenceImage: !!referenceImage,
   323→    });
   324→
   325→    // Create image client and generate image
   326→    const imageClient = new OpenRouterImageClient(apiKey);
   327→
   328→    // Route to appropriate generation method based on generationType
   329→    let result;
   330→    if (generationType === 'fitting-model' && referenceImage) {
   331→      result = await imageClient.generateFittingModelImage(description, referenceImage);
   332→    } else {
   333→      result = await imageClient.generateOutfitImage(description, style);
   334→    }
   335→
   336→    const duration = Date.now() - startTime;
   337→    console.log('[API] Image generation completed in', duration, 'ms', {
   338→      success: result.success,
   339→      error: result.error || 'none',
   340→    });
   341→
   342→    // Return response with appropriate status code
   343→    if (result.success) {
   344→      // Save image to disk and add imageUrl to response
   345→      if (result.imageBase64) {
   346→        try {
   347→          const filename = generateImageFilename();
   348→          const imageUrl = saveBase64Image(result.imageBase64, filename);
   349→          const publicDir = path.join(process.cwd(), 'public', 'generated-images');
   350→          const filePath = path.join(publicDir, filename);
   351→
   352→          // Apply background removal for fitting-model images
   353→          if (generationType === 'fitting-model') {
   354→            console.log('[API] Applying background removal for fitting model');
   355→            const bgRemovalSuccess = await removeBackgroundFromFile(filePath, filePath);
   356→
   357→            if (bgRemovalSuccess) {
   358→              // Re-read the processed image and update base64
   359→              const processedImageBuffer = fs.readFileSync(filePath);
   360→              result.imageBase64 = `data:image/png;base64,${processedImageBuffer.toString('base64')}`;
   361→              console.log('[API] Background removed successfully');
   362→            } else {
   363→              console.warn('[API] Background removal failed, using original image');
   364→            }
   365→          }
   366→
   367→          // Add imageUrl to the result
